def _mock_work_output(feature):
    """Full file content in the same envelope a real model is asked for,
    so the mock exercises the actual parse/diff path rather than a
    special case. Targets a new file, so it applies to any project."""
    path = f"notes/{feature}-mock.md"
    return (
        f"<<<SPECOPS_FILE {path}>>>\n"
        f"# Mock work output for {feature}\n"
        "\n"
        "This is a placeholder artifact generated by the mock adapter.\n"
        "<<<SPECOPS_END>>>\n"
    )


def send_prompt(prompt_text, context):
    meta = context.get("meta", {})
    phase = meta.get("phase")
    feature = meta.get("feature") or "example"

    if phase == "work":
        response_text = _mock_work_output(feature)
    else:
        response_text = (
            "MOCK_RESPONSE\n\n"
            "# Example output\n"
            "- domains:\n"
            "  - Example\n"
            "- bounded_contexts:\n"
            "  - ExampleContext\n"
        )

    return {
        "response_text": response_text,
        "prompt_hash": meta.get("prompt_hash"),
        "rag_sources": meta.get("rag_sources", []),
        "model": "mock",
    }
